<?php

declare(strict_types=1);

namespace ITFlow\Reporting;

use RivetCore\Reporting\ReportingCatalog;
use RivetCore\Reporting\ReportingRole;
use RivetCore\Reporting\ReportingSchema;

/**
 * Everything the Administration > Reporting / Power BI page does that is not markup (RivetCore issue #91, phase 4). No secret is stored or logged here:
 * the database administrator's login is used once over its own connection and forgotten; the reporting account's password is generated by
 * ReportingRole::generatePassword(), returned to the caller ONCE and never written anywhere by this class.
 */
final class ReportingAdmin
{
    /** Every message that leaves this class goes through this, so a password can never ride along in an error text. */
    private static function clean(string $text, string ...$secrets): string
    {
        foreach ($secrets as $s) {
            if ($s !== '') {
                $text = str_replace($s, '[hidden]', $text);
            }
        }
        $text = (string) preg_replace('/\s+/', ' ', $text);

        return mb_substr($text, 0, 300);
    }

    /**
     * Run one statement whatever mysqli's error mode is (the application uses exceptions, a test harness may not): a failure always becomes a \RuntimeException
     * carrying the server's text.
     *
     * @return \mysqli_result|bool
     */
    private static function run(\mysqli $conn, string $sql)
    {
        try {
            $r = @mysqli_query($conn, $sql);
        } catch (\mysqli_sql_exception $e) {
            throw new \RuntimeException($e->getMessage());
        }
        if ($r === false) {
            throw new \RuntimeException(mysqli_error($conn));
        }

        return $r;
    }

    /** Connect in either error mode; throws \RuntimeException with the server's text. */
    private static function connect(string $host, string $user, string $pass, ?string $database, int $port, bool $tls = false): \mysqli
    {
        $c = mysqli_init();
        mysqli_options($c, MYSQLI_OPT_CONNECT_TIMEOUT, 8);
        try {
            $ok = @mysqli_real_connect($c, $host, $user, $pass, $database, $port, null, $tls ? MYSQLI_CLIENT_SSL : 0);
        } catch (\mysqli_sql_exception $e) {
            throw new \RuntimeException($e->getMessage());
        }
        if ($ok === false) {
            throw new \RuntimeException(mysqli_connect_error() ?: 'connection failed');
        }

        return $c;
    }

    /** @return list<string> SELECT grants on the edition's own views for $account (already quoted, e.g. 'u'@'h'). */
    public static function editionGrants(string $database, string $account): array
    {
        $out = [];
        foreach (EditionViews::names() as $v) {
            $out[] = 'GRANT SELECT ON `' . $database . '`.`' . $v . '` TO ' . $account;
        }

        return $out;
    }

    /** @return list<string> the Core views to grant: all of them, except the unscoped audit view unless asked for. */
    public static function coreViewsToGrant(bool $includeAudit): array
    {
        return array_values(array_filter(ReportingSchema::viewNames('mariadb'), static fn (string $v): bool => $includeAudit || $v !== 'rpt_audit_events'));
    }

    /**
     * The status table: Core views (from the catalog) and the edition's, with whether each exists in this database.
     *
     * @return array{core:list<array<string,mixed>>, edition:list<array<string,mixed>>, coreMigration:bool, editionZone:?array<string,mixed>}
     */
    public static function status(\mysqli $db, string $database): array
    {
        $have = [];
        $r = mysqli_prepare($db, "SELECT TABLE_NAME FROM information_schema.VIEWS WHERE TABLE_SCHEMA = ? AND TABLE_NAME LIKE 'rpt\\_%'");
        mysqli_stmt_bind_param($r, 's', $database);
        mysqli_stmt_execute($r);
        $res = mysqli_stmt_get_result($r);
        while ($res && ($row = mysqli_fetch_row($res))) {
            $have[(string) $row[0]] = true;
        }
        $core = [];
        foreach (ReportingCatalog::views() as $v) {
            $core[] = ['name' => $v->name, 'grain' => $v->grain, 'purpose' => $v->purpose, 'scoped' => $v->clientScoped, 'store' => $v->store, 'exists' => isset($have[$v->name])];
        }
        $edition = [];
        foreach (EditionViews::names() as $n) {
            $edition[] = ['name' => $n, 'scoped' => in_array($n, EditionViews::CLIENT_SCOPED, true), 'exists' => isset($have[$n]), 'columns' => EditionViews::COLUMNS[$n]];
        }
        $mig = @mysqli_query($db, "SELECT 1 FROM rivet_core_migrations WHERE migration_id = '0047_reporting_views'");

        return ['core' => $core, 'edition' => $edition, 'coreMigration' => (bool) ($mig && mysqli_num_rows($mig) > 0), 'editionZone' => self::zoneState($db)];
    }

    /** @return array{zone:?string, utc:bool, converted:bool, usable:bool}|null null when the tickets view does not exist */
    public static function zoneState(\mysqli $db): ?array
    {
        $r = @mysqli_query($db, 'SHOW CREATE VIEW rpt_tickets');
        $row = $r ? mysqli_fetch_row($r) : null;
        if ($row === null) {
            return null;
        }
        $zone = EditionViews::companyZone($db);
        $utc = EditionViews::isUtc($zone);

        return ['zone' => $zone, 'utc' => $utc, 'converted' => stripos((string) $row[1], 'CONVERT_TZ') !== false, 'usable' => $utc || ($zone !== null && EditionViews::zoneUsable($db, $zone))];
    }

    /**
     * Warnings computed from the live server, not static text.
     *
     * @return list<string>
     */
    public static function warnings(\mysqli $db, string $accountHost, bool $requireTls): array
    {
        $w = [];
        if ($accountHost === '%' || $accountHost === '') {
            $w[] = "The account's host part is '%': any address may try to sign in. Use the Power BI gateway's address instead.";
        }
        if (!$requireTls) {
            $w[] = 'TLS is not required for this account: the password and the data cross the network in clear text.';
        }
        $v = [];
        $r = @mysqli_query($db, "SHOW VARIABLES WHERE Variable_name IN ('have_ssl', 'have_openssl', 'ssl_cert', 'bind_address', 'port')");
        while ($r && ($row = mysqli_fetch_row($r))) {
            $v[strtolower((string) $row[0])] = (string) $row[1];
        }
        $ssl = $v['have_ssl'] ?? $v['have_openssl'] ?? '';
        if ($ssl !== '' && strtoupper($ssl) !== 'YES' || ($ssl === '' && ($v['ssl_cert'] ?? '') === '')) {
            $w[] = 'This database server does not offer TLS (have_ssl is ' . ($ssl === '' ? 'unknown' : $ssl) . '): a REQUIRE SSL account cannot connect until TLS is configured.';
        }
        $bind = $v['bind_address'] ?? '';
        if ($bind === '' || $bind === '0.0.0.0' || $bind === '*' || $bind === '::') {
            $w[] = 'The database server listens on ' . ($bind === '' ? 'all addresses' : $bind) . '. Open its port only to the reporting gateway.';
        } elseif (!self::isPrivateAddress($bind) && !in_array($bind, ['localhost'], true)) {
            $w[] = "The database server is bound to a public-looking address ($bind).";
        } elseif (in_array($bind, ['127.0.0.1', '::1', 'localhost'], true)) {
            $w[] = 'The database server listens on the loopback address only: Power BI on another machine cannot reach it without a tunnel or a changed bind-address.';
        }

        return $w;
    }

    private static function isPrivateAddress(string $a): bool
    {
        return filter_var($a, FILTER_VALIDATE_IP) !== false && filter_var($a, FILTER_VALIDATE_IP, FILTER_FLAG_NO_PRIV_RANGE | FILTER_FLAG_NO_RES_RANGE) === false;
    }

    /**
     * Create or rotate the MariaDB/MySQL reporting account with a separate administrator login.
     *
     * @param array{host:string, port:int, user:string, pass:string} $admin used once, never kept
     * @return array{password:string, user:string, host:string, statements:int}
     * @throws \InvalidArgumentException a message safe to show
     */
    public static function provisionMariadb(array $admin, string $database, string $user, string $host, bool $requireTls, bool $includeAudit): array
    {
        $password = ReportingRole::generatePassword();
        // The Core builder validates the identifiers, the host part and the database name and refuses anything hostile.
        $statements = ReportingRole::mariadbStatements($database, $password, $user, $host, $requireTls, self::coreViewsToGrant($includeAudit));
        $statements = array_merge($statements, self::editionGrants($database, "'" . $user . "'@'" . $host . "'"));
        $statements[] = 'FLUSH PRIVILEGES';
        $conn = self::adminConnection($admin, $password);
        try {
            foreach ($statements as $sql) {
                try {
                    self::run($conn, $sql);
                } catch (\RuntimeException $e) {
                    throw new \InvalidArgumentException('The statement ' . self::clean(strtok($sql, "\n") ?: '', $password, $admin['pass']) . ' failed: ' . self::clean($e->getMessage(), $password, $admin['pass']));
                }
            }
        } finally {
            mysqli_close($conn);
        }

        return ['password' => $password, 'user' => $user, 'host' => $host, 'statements' => count($statements)];
    }

    /** @throws \InvalidArgumentException */
    public static function dropMariadb(array $admin, string $user, string $host): void
    {
        $conn = self::adminConnection($admin, '');
        try {
            foreach (ReportingRole::dropMariadbStatements($user, $host) as $sql) {
                self::run($conn, $sql);
            }
        } catch (\RuntimeException $e) {
            throw new \InvalidArgumentException('Dropping the account failed: ' . self::clean($e->getMessage(), $admin['pass']));
        } finally {
            mysqli_close($conn);
        }
    }

    /**
     * PostgreSQL: the statements run over the data store's OWN stored connection (the sealed one), the role of which must be allowed to create roles.
     *
     * @return array{password:string, user:string, statements:int}
     * @throws \InvalidArgumentException
     */
    public static function provisionPostgres(\RivetCore\Rmm\Store\Postgres\PostgresConfig $cfg, string $user, bool $drop = false): array
    {
        $password = $drop ? '' : ReportingRole::generatePassword();
        $statements = $drop ? ReportingRole::dropPostgresStatements($cfg->database, $user, $cfg->schema) : ReportingRole::postgresStatements($cfg->database, $password, $user, $cfg->schema);
        try {
            $pdo = new \PDO($cfg->dsn(), $cfg->user, $cfg->password(), [\PDO::ATTR_ERRMODE => \PDO::ERRMODE_EXCEPTION, \PDO::ATTR_TIMEOUT => 10]);
            foreach ($statements as $sql) {
                $pdo->exec($sql);
            }
        } catch (\PDOException $e) {
            throw new \InvalidArgumentException('PostgreSQL refused: ' . self::clean($e->getMessage(), $password, $cfg->password()));
        }

        return ['password' => $password, 'user' => $user, 'statements' => count($statements)];
    }

    /** @return \mysqli */
    private static function adminConnection(array $admin, string $alsoHide)
    {
        $host = (string) $admin['host'];
        if ($host === '' || preg_match('/^[A-Za-z0-9_.:\-\/]{1,255}$/', $host) !== 1 || (int) $admin['port'] < 1 || (int) $admin['port'] > 65535 || $admin['user'] === '' || strlen($admin['user']) > 80) {
            throw new \InvalidArgumentException('Enter the database server host, port and an administrator login.');
        }
        try {
            return self::connect($host, (string) $admin['user'], (string) $admin['pass'], null, (int) $admin['port']);
        } catch (\RuntimeException $e) {
            throw new \InvalidArgumentException('Could not sign in to the database server as that administrator: ' . self::clean($e->getMessage(), (string) $admin['pass'], $alsoHide));
        }
    }

    /**
     * Connect AS the reporting account and check what it can and cannot do. The password is typed by the administrator and kept nowhere.
     *
     * @return list<array{name:string, ok:bool, detail:string}>
     */
    public static function testConnection(string $host, int $port, string $database, string $user, string $password, bool $tls): array
    {
        $out = [];
        try {
            $conn = self::connect($host, $user, $password, $database, $port, $tls);
            $out[] = ['name' => 'Sign in as the reporting account', 'ok' => true, 'detail' => 'Connected' . ($tls ? ' with TLS' : '') . '.'];
        } catch (\RuntimeException $e) {
            return [['name' => 'Sign in as the reporting account', 'ok' => false, 'detail' => self::clean($e->getMessage(), $password)]];
        }
        try {
            $r = self::run($conn, 'SELECT COUNT(*) FROM rpt_devices');
            $out[] = ['name' => 'Read a reporting view (rpt_devices)', 'ok' => true, 'detail' => (int) mysqli_fetch_row($r)[0] . ' row(s).'];
        } catch (\RuntimeException $e) {
            $out[] = ['name' => 'Read a reporting view (rpt_devices)', 'ok' => false, 'detail' => self::clean($e->getMessage(), $password)];
        }
        foreach (['users', 'clients'] as $base) {
            try {
                self::run($conn, "SELECT 1 FROM `$base` LIMIT 1");
                $out[] = ['name' => "Read the base table $base (must be refused)", 'ok' => false, 'detail' => 'The account CAN read it. Rotate the account and check its grants.'];
            } catch (\RuntimeException $e) {
                $out[] = ['name' => "Read the base table $base (must be refused)", 'ok' => true, 'detail' => 'Refused: ' . self::clean($e->getMessage(), $password)];
            }
        }
        mysqli_close($conn);

        return $out;
    }

    /**
     * The Power Query sample for one view, with this install's real server and database filled in.
     *
     * @return ?string null when there is no sample for that view
     */
    public static function powerQuery(string $dialect, string $view, string $server, string $database, string $packageRoot): ?string
    {
        if (preg_match('/^rpt_[a-z0-9_]+$/', $view) !== 1 || !in_array($dialect, ['mysql-mariadb', 'postgresql'], true)) {
            return null;
        }
        $file = $packageRoot . '/docs/reporting/samples/power-query/' . $dialect . '/' . $view . '.pq';
        $text = is_file($file) ? (string) file_get_contents($file) : '';
        if ($text === '') {
            return null;
        }
        $lit = static fn (string $s): string => '"' . str_replace('"', '""', $s) . '"';

        // The samples read two query parameters (ServerName, DatabaseName). Declare them at the top of the query so the pasted text runs as it is.
        $declared = "let\n    ServerName = " . $lit($server) . ",\n    DatabaseName = " . $lit($database) . ',';

        return preg_replace('/^let\s*$/m', $declared, $text, 1) ?? $text;
    }
}
